//! The rynas Task Scheduler (D-TASKS): every task is a pair of persistent systemd units
//! generated by rynasd from the `scheduler` configuration key
//! (`/etc/systemd/system/rynas-task-<id>.{service,timer}`, managed header and hash).
//!
//! - [`domain`]: the configuration domain (validation, rendering, apply/rollback);
//! - [`units`]: the unit files;
//! - [`calendar`]: `OnCalendar=` checks, cron conversion, `systemd-analyze` output;
//! - [`probe`]: read-only systemd questions (timers, journal) behind a trait;
//! - [`history`]: the run history (SQLite) fed by `rynasctl task-finished`;
//! - [`live`]: the live output of a running task (journal entries, event data);
//! - [`cron`]: read-only listing of crontab entries.
//!
//! Run notifications (per-task policy) are emitted by rynasd through `rynas_notify::Notifier`.

pub mod calendar;
pub mod cron;
pub mod domain;
pub mod history;
pub mod live;
pub mod probe;
pub mod units;

pub use domain::{SCHEDULER_KEY, SchedulerDomain};

